questions.safe_code:
1  class Format {
2    static Calendar c = new GregorianCalendar(1995, GregorianCalendar.MAY, 23);
3    public static void main(String[] args) {
4      // 입력값은 %s 인자로 전달하고 포맷 문자열은 고정 문자열로 사용
5      System.out.printf("%s did not match! HINT: It was issued on %2$terd of some month", args[0], c);
6    }
7  }

